var n=`0408-scones`;var t=`world-0408`;var o=`GB`;var a=`northern-europe`;var r=8;var g=36;var s={en:`Scones`,ua:`Скони`};var d={en:`A traditional dish from United Kingdom, centered on all-purpose flour, baking powder, whole cow milk, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: пшеничне борошно універсальне, розпушувач тіста, цільне коров'яче молоко, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`all-purpose-flour`,400,`g`],[`unsalted-butter`,95,`g`],[`white-granulated-sugar`,50,`g`],[`baking-powder`,18,`g`],[`table-salt`,2,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`whole-cow-milk`,200,`ml`],[`chicken-egg`,1,`pcs`]]},{en:`Pat the dough about 2.5 cm thick and cut straight down with a floured cutter; avoid twisting the cutter.`,ua:`Розплескайте тісто до товщини близько 2,5 см, вирізайте формочкою вертикально, не прокручуючи її.`,t:[`pressing`,`rolling-out-dough`],m:6,i:[]},{en:`Bake in a preheated 180°C oven for about 17 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 17 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:17,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`clotted-cream`,180,`g`],[`strawberry-jam`,160,`g`]]}];var u={slug:n,id:t,country:`GB`,region:a,servings:8,minutes:36,title:s,text:d,steps:l};export{o as country,u as default,t as id,g as minutes,a as region,r as servings,n as slug,l as steps,d as text,s as title};